FUNCTION_BLOCK FB
VAR_INPUT
    openBtn   : BOOL;
    closeBtn  : BOOL;
    openLimit : BOOL;
    closeLimit: BOOL;
    obstacle  : BOOL;
END_VAR
VAR_OUTPUT
    motorUp   : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state       : INT;  // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    prevOpenBtn : BOOL;
    prevCloseBtn: BOOL;
END_VAR

// Edge detection for buttons
VAR
    openRising  : BOOL;
    closeRising : BOOL;
END_VAR

openRising  := openBtn AND NOT prevOpenBtn;
closeRising := closeBtn AND NOT prevCloseBtn;

// Save button states for next cycle
prevOpenBtn  := openBtn;
prevCloseBtn := closeBtn;

// Default: motor outputs off
motorUp   := FALSE;
motorDown := FALSE;

// State machine
CASE state OF
    // IDLE state
    0:  // IDLE
        IF openRising AND NOT openLimit THEN
            state := 1;  // Enter OPENING
        ELSIF closeRising AND NOT closeLimit THEN
            state := 2;  // Enter CLOSING
        END_IF

    // OPENING state
    1:  // OPENING
        motorUp := TRUE;
        IF openLimit THEN
            state := 0;  // Back to IDLE
            motorUp := FALSE;
        ELSIF obstacle THEN
            state := 3;  // Enter FAULT
            motorUp := FALSE;
        END_IF

    // CLOSING state
    2:  // CLOSING
        motorDown := TRUE;
        IF closeLimit THEN
            state := 0;  // Back to IDLE
            motorDown := FALSE;
        ELSIF obstacle THEN
            state := 1;  // Reverse to OPENING
            motorDown := FALSE;
        END_IF

    // FAULT state
    3:  // FAULT
        errorFlag := TRUE;
        IF openBtn AND closeBtn THEN
            state := 0;
            errorFlag := FALSE;
        END_IF

END_CASE

END_FUNCTION_BLOCK
